#!/usr/bin/env node
// Fail when README.md or a hand-written doc under docs/ tells the reader to run
// a `kb <command>` that the built CLI does not have (issue #1177, proposal item
// 4: keep docs honest; docs/ coverage added in issue #1287).
//
// docs/ scope: every *.md under docs/ except generated references (files that
// carry the "This file is generated by ... Do not edit by hand." marker, e.g.
// docs/reference/cli.md, which scripts/gen-cli-reference.mjs already keeps in
// sync), docs/rfcs/ (proposals and history that name flags that were never
// shipped or were removed) and docs/testing/fixtures/ (test corpus data).
//
// Source of truth is `kb help --format=json` from the built CLI, the same
// registry scripts/gen-cli-reference.mjs reads. Only code spans (`kb x`) and
// fenced code blocks are scanned, so prose such as "the kb command" is ignored.
//
// It also checks each `--flag` written after a known `kb <command>` (up to the
// next `kb <command>`, pipe, `;` or `&`, so a `# ...` shell comment is checked
// too) against that command's documented options and usage lines (issue #1284).
//
//   node scripts/check-readme-cli-commands.mjs   # exit 1 on unknown commands or flags
//
// Mermaid fences are skipped: their node labels are prose, not shell.

import * as fs from 'node:fs';
import * as path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Words that follow `kb` in README code but are options, shell syntax or
// placeholders rather than subcommands.
const NOT_COMMANDS = new Set(['<command>', '<topic>']);

// Fence languages whose bodies are not shell commands.
const NON_SHELL_FENCES = new Set(['mermaid']);

// Code spans and fenced-block bodies; prose is never scanned.
function readmeCodeChunks(markdown) {
  const code = [];
  const stripped = markdown.replace(/^```([^\n]*)\n([\s\S]*?)^```/gm, (_m, info, body) => {
    if (!NON_SHELL_FENCES.has(info.trim().split(/\s+/)[0])) code.push(body);
    return '\n';
  });
  for (const m of stripped.matchAll(/`([^`\n]+)`/g)) code.push(m[1]);
  return code;
}

export function extractReadmeCommands(markdown) {
  const found = new Set();
  for (const chunk of readmeCodeChunks(markdown)) {
    // `[ \t]+`, not `\s+`: `which -a kb` must not pair with `kb doctor` on the next line.
    for (const m of chunk.matchAll(/(?:^|[\s|;(&$>])kb[ \t]+([a-z][a-z0-9-]*)/gm)) {
      found.add(m[1]);
    }
  }
  return [...found].filter((c) => !NOT_COMMANDS.has(c)).sort();
}

export function findUnknownCommands(markdown, knownCommands) {
  const known = new Set(knownCommands);
  return extractReadmeCommands(markdown).filter((c) => !known.has(c));
}

function knownFlagsOf(command) {
  const flags = new Set();
  for (const opt of command.options ?? []) for (const f of opt.flags ?? []) flags.add(f);
  for (const u of command.usage ?? []) for (const m of u.matchAll(/--[a-z][a-z0-9-]*/g)) flags.add(m[0]);
  return flags;
}

// Returns `kb <cmd> --flag` strings for flags the registry does not document
// for that command. `registry` is the parsed `kb help --format=json` list.
// Commands absent from the registry are skipped (findUnknownCommands reports them).
export function findUnknownFlags(markdown, registry) {
  const byName = new Map(registry.map((c) => [c.name, c]));
  const bad = new Set();
  for (const chunk of readmeCodeChunks(markdown)) {
    // Join `\`-continued lines so a multi-line command is checked as one.
    for (const line of chunk.replace(/\\\n/g, ' ').split('\n')) {
      const starts = [...line.matchAll(/(?:^|[\s|;(&$>])kb\s+([a-z][a-z0-9-]*)/g)];
      starts.forEach((m, i) => {
        const command = byName.get(m[1]);
        if (!command) return;
        const end = i + 1 < starts.length ? starts[i + 1].index : undefined;
        const segment = line.slice(m.index + m[0].length, end).split(/[|;&]/)[0];
        const known = knownFlagsOf(command);
        for (const f of segment.matchAll(/(?:^|\s)(--[a-z][a-z0-9-]*)/g)) {
          if (!known.has(f[1])) bad.add(`kb ${m[1]} ${f[1]}`);
        }
      });
    }
  }
  return [...bad].sort();
}

function loadRegistry() {
  const cli = path.join(REPO_ROOT, 'build/cli.js');
  if (!fs.existsSync(cli)) throw new Error('build/cli.js not found; run `npm run build` first.');
  const r = spawnSync(process.execPath, [cli, 'help', '--format=json'], {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  if (r.status !== 0) throw new Error(`kb help --format=json exited ${r.status}: ${r.stderr}`);
  const parsed = JSON.parse(r.stdout);
  return Array.isArray(parsed) ? parsed : (parsed.commands ?? []);
}

// docs/ subtrees that are not checked; see the header comment for why.
export const DOCS_EXCLUDED_DIRS = ['docs/rfcs/', 'docs/testing/fixtures/'];

const GENERATED_MARKER = /This file is generated by [^\n]*Do not edit by hand/;

export function isGeneratedDoc(markdown) {
  return GENERATED_MARKER.test(markdown.slice(0, 2000));
}

// Repo-relative POSIX paths of README.md plus the hand-written docs/**/*.md,
// sorted. Generated files are dropped by the caller, which reads each file.
export function listDocFiles(root = REPO_ROOT) {
  const out = ['README.md'];
  const walk = (rel) => {
    for (const entry of fs.readdirSync(path.join(root, rel), { withFileTypes: true })) {
      const child = `${rel}/${entry.name}`;
      if (entry.isDirectory()) {
        if (!DOCS_EXCLUDED_DIRS.includes(`${child}/`)) walk(child);
      } else if (entry.isFile() && entry.name.endsWith('.md')) {
        out.push(child);
      }
    }
  };
  if (fs.existsSync(path.join(root, 'docs'))) walk('docs');
  return [out[0], ...out.slice(1).sort()];
}

// Checks each `{ file, markdown }` against the registry. Returns
// `{ commands, flags }`, each a list of `<file>: kb <cmd>[ --flag]` strings.
export function checkDocs(docs, registry) {
  // `help` is handled before the SUBCOMMANDS registry lookup.
  const names = [...registry.map((c) => c.name), 'help'];
  const commands = [];
  const flags = [];
  for (const { file, markdown } of docs) {
    for (const c of findUnknownCommands(markdown, names)) commands.push(`${file}: kb ${c}`);
    for (const f of findUnknownFlags(markdown, registry)) flags.push(`${file}: ${f}`);
  }
  return { commands, flags };
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const docs = listDocFiles()
    .map((file) => ({ file, markdown: fs.readFileSync(path.join(REPO_ROOT, file), 'utf8') }))
    .filter((d) => !isGeneratedDoc(d.markdown));
  const { commands, flags } = checkDocs(docs, loadRegistry());
  if (commands.length > 0) {
    console.error(`Docs reference kb commands the CLI does not have:\n  ${commands.join('\n  ')}`);
  }
  if (flags.length > 0) {
    console.error(`Docs reference kb flags the CLI does not have:\n  ${flags.join('\n  ')}`);
  }
  if (commands.length > 0 || flags.length > 0) process.exit(1);
  console.log(`kb command and flag references in README.md and ${docs.length - 1} hand-written docs: OK`);
}
